<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$tracks=$pdo?$pdo->query('SELECT id,title,category,status,plays FROM audio_tracks ORDER BY updated_at DESC')->fetchAll():[];?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audio Library</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><main class="container"><h1>Audio Library</h1><p><a class="btn" href="audio-edit.php">New audio</a> <a href="dashboard.php">Dashboard</a></p><div class="card" style="overflow:auto"><table style="width:100%"><tr><th>Title</th><th>Category</th><th>Status</th><th>Plays</th><th>Actions</th></tr><?php foreach($tracks as $t):?><tr><td><?=e($t['title'])?></td><td><?=e($t['category']??'')?></td><td><?=e($t['status'])?></td><td><?=e((string)$t['plays'])?></td><td><a href="audio-edit.php?id=<?=$t['id']?>">Edit</a> · <a href="audio-delete.php?id=<?=$t['id']?>">Delete</a></td></tr><?php endforeach;?></table><?php if(!$tracks):?><p class="muted">No audio tracks found.</p><?php endif;?></div></main></body></html>
